import{_ as t,o as a,c as i,ai as n}from"./chunks/framework.DnX3IzGy.js";const p=JSON.parse('{"title":"OAuth2 Credentials Delegation","description":"","frontmatter":{},"headers":[],"relativePath":"integrator-guide/oauth2/delegation.md","filePath":"integrator-guide/oauth2/delegation.md"}'),o={name:"integrator-guide/oauth2/delegation.md"};function d(l,e,r,s,c,h){return a(),i("div",null,e[0]||(e[0]=[n('<h1 id="oauth2-credentials-delegation" tabindex="-1">OAuth2 Credentials Delegation <a class="header-anchor" href="#oauth2-credentials-delegation" aria-label="Permalink to &quot;OAuth2 Credentials Delegation&quot;">​</a></h1><p>Citizen iD supports OAuth2 credentials delegation, allowing OAuth2 applications to delegate access to the user account and resources to third-party applications. This is achieved through the OAuth2 token exchange flow. This guide provides an overview of how to delegate, look up, and revoke OAuth2 credentials using Citizen iD.</p><h2 id="delegating-credentials" tabindex="-1">Delegating Credentials <a class="header-anchor" href="#delegating-credentials" aria-label="Permalink to &quot;Delegating Credentials&quot;">​</a></h2><p>To delegate credentials to another application, use the <a href="./flows-grants.html#token-exchange">Token Exchange flow</a>. This allows your application to exchange an existing access token for a new one that is scoped to a different client application, optionally with a reduced set of scopes.</p><p>The resulting token will include an <code>act</code> (actor) claim identifying the application that the credentials were delegated to. This ensures that the original user&#39;s identity is preserved while indicating that the credentials are being used on behalf of a specific application.</p><h2 id="looking-up-delegated-credentials" tabindex="-1">Looking Up Delegated Credentials <a class="header-anchor" href="#looking-up-delegated-credentials" aria-label="Permalink to &quot;Looking Up Delegated Credentials&quot;">​</a></h2><p>Delegated credentials can be identified by inspecting the <code>act</code> claim in the access token. If the <code>act</code> claim is present, it indicates that the token was obtained through credential delegation. The claim contains the <code>sub</code> (subject) and <code>name</code> of the actor application.</p><p>Additionally, Citizen iD provides API endpoints to list and filter delegated tokens for currently authenticated application (<code>client_credentials</code>). These APIs also support revoking delegated tokens directly, offering an alternative to the standard OAuth2 revocation flow.</p><h2 id="revoking-delegated-credentials" tabindex="-1">Revoking Delegated Credentials <a class="header-anchor" href="#revoking-delegated-credentials" aria-label="Permalink to &quot;Revoking Delegated Credentials&quot;">​</a></h2><p>Delegated tokens can be revoked using the standard <a href="./flows-grants.html#token-revocation">Token Revocation</a> endpoint. Both the original application and the delegate can revoke the token. When revoked, the token is immediately invalidated and can no longer be used.</p><hr><p><em>Last updated: February 2026</em></p>',12)]))}const u=t(o,[["render",d]]);export{p as __pageData,u as default};
